import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.hw3Av5Vn.js";const m=JSON.parse('{"title":"Electronic","description":"","frontmatter":{},"headers":[],"relativePath":"demos/ELECTRONIC_MASHUP.md","filePath":"demos/ELECTRONIC_MASHUP.md"}'),n={name:"demos/ELECTRONIC_MASHUP.md"};function s(i,e,h,l,c,d){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="electronic" tabindex="-1">Electronic <a class="header-anchor" href="#electronic" aria-label="Permalink to &quot;Electronic&quot;">​</a></h1><p>The mashups that set another work&#39;s notes on a electronic band. Each is described below, with the features it uses; <a href="./../DEMOS">About Demos</a> lists every demo.</p><ul><li><a href="#can_can_cant_stop">The Can-Can as Happy Hardcore</a>: <code>can_can_cant_stop.yml</code></li><li><a href="#chipped_jazz">The Maple Leaf Rag as a Chiptune</a>: <code>chipped_jazz.yml</code></li><li><a href="#house_entertainer">The Entertainer as Piano House</a>: <code>house_entertainer.yml</code></li><li><a href="#jungle_alarm_clock">Morning Mood as Jungle</a>: <code>jungle_alarm_clock.yml</code></li><li><a href="#south_florida_squad">The Moonlight Sonata&#39;s Last Movement as an Eighties Synthesizer Action Score</a>: <code>south_florida_squad.yml</code></li><li><a href="#tripped_went_to_hospital">St. James Infirmary as Trip Hop</a>: <code>tripped_went_to_hospital.yml</code></li><li><a href="#zap_swing_kapow">The Charleston as Electro Swing</a>: <code>zap_swing_kapow.yml</code></li></ul><p><a id="can_can_cant_stop"></a></p><h2 id="the-can-can-as-happy-hardcore-can-can-cant-stop-yml" tabindex="-1">The Can-Can as Happy Hardcore: <code>can_can_cant_stop.yml</code> <a class="header-anchor" href="#the-can-can-as-happy-hardcore-can-can-cant-stop-yml" aria-label="Permalink to &quot;The Can-Can as Happy Hardcore: `can_can_cant_stop.yml`&quot;">​</a></h2><p>Can-can can&#39;t stop: the Can-Can as nineties happy hardcore. The galop from Orpheus in the Underworld (Jacques Offenbach, 1858) is public domain and is played as written, from Claude&#39;s knowledge of the score, in its key and then in the key a fifth above; the rave piano, the offbeat bass, the arpeggios, the solos and the drums are new.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/mashups/electronic/can_can_cant_stop.yml" target="_blank" rel="noreferrer"><code>examples/mashups/electronic/can_can_cant_stop.yml</code></a> · D major · 172 BPM · 2:59 · 15 scenes · 10 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ties</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td></tr></tbody></table><p><a id="chipped_jazz"></a></p><h2 id="the-maple-leaf-rag-as-a-chiptune-chipped-jazz-yml" tabindex="-1">The Maple Leaf Rag as a Chiptune: <code>chipped_jazz.yml</code> <a class="header-anchor" href="#the-maple-leaf-rag-as-a-chiptune-chipped-jazz-yml" aria-label="Permalink to &quot;The Maple Leaf Rag as a Chiptune: `chipped_jazz.yml`&quot;">​</a></h2><p>Chipped jazz: the Maple Leaf Rag as a chiptune. The first two strains of the Maple Leaf Rag (Scott Joplin, 1899) are public domain and are played as written, read from the corpus&#39;s edition of the piano score; the arpeggios, the bass, the second voice&#39;s answers, the solos and the drums are new.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/mashups/electronic/chipped_jazz.yml" target="_blank" rel="noreferrer"><code>examples/mashups/electronic/chipped_jazz.yml</code></a> · Ab major · 116 BPM · 2:54 · 12 scenes · 7 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">ties</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td></tr></tbody></table><p><a id="house_entertainer"></a></p><h2 id="the-entertainer-as-piano-house-house-entertainer-yml" tabindex="-1">The Entertainer as Piano House: <code>house_entertainer.yml</code> <a class="header-anchor" href="#the-entertainer-as-piano-house-house-entertainer-yml" aria-label="Permalink to &quot;The Entertainer as Piano House: `house_entertainer.yml`&quot;">​</a></h2><p>House entertainer: The Entertainer as piano house. The first two strains of The Entertainer (Scott Joplin, 1902) are public domain and are played as written, read from the corpus&#39;s edition of the piano score; the house chords, the bass, the organ&#39;s answers, the solos and the drums are new.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/mashups/electronic/house_entertainer.yml" target="_blank" rel="noreferrer"><code>examples/mashups/electronic/house_entertainer.yml</code></a> · C major · 124 BPM · 2:58 · 11 scenes · 11 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ties</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td></tr></tbody></table><p><a id="jungle_alarm_clock"></a></p><h2 id="morning-mood-as-jungle-jungle-alarm-clock-yml" tabindex="-1">Morning Mood as Jungle: <code>jungle_alarm_clock.yml</code> <a class="header-anchor" href="#morning-mood-as-jungle-jungle-alarm-clock-yml" aria-label="Permalink to &quot;Morning Mood as Jungle: `jungle_alarm_clock.yml`&quot;">​</a></h2><p>Jungle alarm clock: Morning Mood as nineties jungle. The opening tune of Morning Mood from Peer Gynt (Edvard Grieg, 1875) is public domain; its pitches are played in their order, from Claude&#39;s knowledge of the score, each bar&#39;s six notes spread over the breakbeat as three, three and two, and it comes back a third higher as the composer brings it back; the chopped breakbeats, the sub bass, the stabs, the piano&#39;s answers and the stretches of drums and bass alone are new.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/mashups/electronic/jungle_alarm_clock.yml" target="_blank" rel="noreferrer"><code>examples/mashups/electronic/jungle_alarm_clock.yml</code></a> · E major · 168 BPM · 3:03 · 14 scenes · 11 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ties</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td></tr></tbody></table><p><a id="south_florida_squad"></a></p><h2 id="the-moonlight-sonata-s-last-movement-as-an-eighties-synthesizer-action-score-south-florida-squad-yml" tabindex="-1">The Moonlight Sonata&#39;s Last Movement as an Eighties Synthesizer Action Score: <code>south_florida_squad.yml</code> <a class="header-anchor" href="#the-moonlight-sonata-s-last-movement-as-an-eighties-synthesizer-action-score-south-florida-squad-yml" aria-label="Permalink to &quot;The Moonlight Sonata&#39;s Last Movement as an Eighties Synthesizer Action Score: `south_florida_squad.yml`&quot;">​</a></h2><p>South Florida squad: the storm of the Moonlight Sonata as an eighties cop show&#39;s theme, after the Miami Vice theme (Jan Hammer). The opening arpeggios and the second theme of the last movement of the Piano Sonata No. 14 (Ludwig van Beethoven, 1801) are public domain and are played as written, read from the corpus&#39;s score; the drum machine, the percussion, the bass, the brass stabs, the solos and the tom-tom breaks are new, with nothing of the reference&#39;s own tune quoted.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/mashups/electronic/south_florida_squad.yml" target="_blank" rel="noreferrer"><code>examples/mashups/electronic/south_florida_squad.yml</code></a> · C# minor · 126 BPM · 3:03 · 16 scenes · 14 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ties</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td></tr></tbody></table><p><a id="tripped_went_to_hospital"></a></p><h2 id="st-james-infirmary-as-trip-hop-tripped-went-to-hospital-yml" tabindex="-1">St. James Infirmary as Trip Hop: <code>tripped_went_to_hospital.yml</code> <a class="header-anchor" href="#st-james-infirmary-as-trip-hop-tripped-went-to-hospital-yml" aria-label="Permalink to &quot;St. James Infirmary as Trip Hop: `tripped_went_to_hospital.yml`&quot;">​</a></h2><p>Tripped, went to hospital: St. James Infirmary as nineties trip hop. The tune of St. James Infirmary (traditional) is public domain and is played as written, with its chords, read from the corpus&#39;s lead sheet; the slow breakbeat, the bass, the electric piano, the vibraphone&#39;s answers and the solos are new.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/mashups/electronic/tripped_went_to_hospital.yml" target="_blank" rel="noreferrer"><code>examples/mashups/electronic/tripped_went_to_hospital.yml</code></a> · D minor · 80 BPM · 3:00 · 11 scenes · 10 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ties</th><th style="text-align:center;">grooves</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../GROOVES">✓</a></td></tr></tbody></table><p><a id="zap_swing_kapow"></a></p><h2 id="the-charleston-as-electro-swing-zap-swing-kapow-yml" tabindex="-1">The Charleston as Electro Swing: <code>zap_swing_kapow.yml</code> <a class="header-anchor" href="#the-charleston-as-electro-swing-zap-swing-kapow-yml" aria-label="Permalink to &quot;The Charleston as Electro Swing: `zap_swing_kapow.yml`&quot;">​</a></h2><p>Zap swing kapow: the Charleston as electro swing. The tune of the Charleston (James P. Johnson, 1923) is public domain and is played as written, with its chords, read from the corpus&#39;s lead sheet; the dance beat, the bass, the piano&#39;s offbeats, the clarinet&#39;s and trumpet&#39;s answers and the solos are new.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/mashups/electronic/zap_swing_kapow.yml" target="_blank" rel="noreferrer"><code>examples/mashups/electronic/zap_swing_kapow.yml</code></a> · Bb major · 126 BPM · 3:01 · 11 scenes · 10 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ties</th><th style="text-align:center;">grooves</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../GROOVES">✓</a></td></tr></tbody></table>',38)])])}const u=a(n,[["render",s]]);export{m as __pageData,u as default};
